by_alias.map:
function(doc) {
  if (doc.type !== "site" || doc.active !== true) return;
  var aliases = doc.aliases || [];
  for (var i = 0; i < aliases.length; i++) {
    emit(aliases[i].toLowerCase().replace(/\s+/g, " ").trim(), {
      site_id: doc.site_id,
      canonical: doc.account,
      note_path: doc.note_path,
      vision_context: doc.vision_context || null
    });
  }
}

by_site_id.map:
function(doc) {
  if (doc.type !== "site" || doc.active !== true) return;
